1	// The page: holds one image's candidates and redraws everything from their current results.
2	// All detection and filtering is Python (detection/interactive.py) running in worker.js; this
3	// file only draws, keeps the user's settings, decisions and measurements, and asks the worker to refilter.
4	"use strict";
5	const $ = (s) => document.querySelector(s);
6	const SVGNS = "http://www.w3.org/2000/svg";
7	const STORE = "nor-filter-settings-v1"; // {values: {param: number}, off: [filter key]}; only what the user changed
8	const THEME = "nor-theme"; // "dark" | "light"; absent = follow the system
9	const MARKS = "nor-marks-v1:"; // + file name + "|" + finder: {"x,y": "in" | "out"}, the user's keepers and removals
10	const EDITS = "nor-edits-v1:"; // + file name + "|" + finder: {"x,y": {length, red, approved}}, the user's measurements
11	const SHOW = "nor-show-v1"; // the image view's Show menu
12	const CARDS = "nor-cards-v3"; // the item views' Options menu, one per view: {pass: {...}, fail: {...}}, only what the user changed
13	const BARS = "nor-bars-v1"; // {left, right}: side bar widths in pixels
14	const SOURCE = "nor-load-source"; // "local" | "drive": where Load reads from
15	const DRIVE_LINK = "nor-drive-link"; // the last Google Drive link pasted
16	const MEASURES = [
17	  ["length", "length", true], ["red_length", "red length", true], ["width", "width", true],
18	  ["red_over_length", "red / length", false], ["length_over_width", "length / width", false],
19	];
20	const BY_YOU = "rejected by you";
21	const SHOW_DEFAULTS = { pass: true, fails: true, nums: true, letters: true, lines: true, passW: 1, passC: "#ff69c8", failW: 1, failC: "#008cff" };
22	// each item view opens with its own options: the finalists with everything needed to check and adjust
23	// lengths, the rejected with just the NoR's borders and more context around it
24	const CARD_DEFAULTS = {
25	  pass: { pad: 4, align: true, borders: true, bars: true, lenImg: true, lenCard: false, adjust: true },
26	  fail: { pad: 10, align: false, borders: true, bars: false, lenImg: false, lenCard: false, adjust: false },
27	};
28	
29	const st = {
30	  worker: null, H: 0, W: 0, um: null, img: null, meta: null, seg: null, cands: [],
31	  fails: [], alone: null, forced: new Map(), edits: new Map(), defaults: {}, values: {}, off: new Set(),
32	  about: {}, detectValues: {}, lastRun: null, filtersFor: null, seq: 0, inflight: false, pending: false,
33	  zoom: 2, fileName: "", sha: "", numbers: new Map(), order: [], times: {}, sel: null, tab: "pass",
34	  show: { ...SHOW_DEFAULTS, ...readJSON(SHOW) }, opt: readOpts(), crops: new Map(),
35	};
36	
37	function readJSON(key, fallback = {}) {
38	  try { return JSON.parse(localStorage.getItem(key)) || fallback; } catch { return fallback; }
39	}
40	function readOpts() {
41	  const saved = readJSON(CARDS);
42	  return { pass: { ...CARD_DEFAULTS.pass, ...saved.pass }, fail: { ...CARD_DEFAULTS.fail, ...saved.fail } };
43	}
44	// the options a candidate's card is drawn with: those of the view it is listed in
45	const optsOf = (c) => st.opt[result(c.i) === null ? "pass" : "fail"];
46	function writeJSON(key, v) {
47	  try { localStorage.setItem(key, JSON.stringify(v)); } catch { /* private mode: lasts for this page only */ }
48	}
49	
50	// ---------- saved filter settings ----------
51	const loadSaved = () => readJSON(STORE, { values: {}, off: [] });
52	function save() {
53	  const values = {};
54	  for (const [k, v] of Object.entries(st.values)) if (v !== st.defaults[k]) values[k] = v;
55	  writeJSON(STORE, { values, off: [...st.off] });
56	}
57	
58	// ---------- the user's decisions and measurements: saved per file and finder, tied to each candidate's position ----------
59	const posKey = (c) => `${Math.round(c.cx)},${Math.round(c.cy)}`;
60	const fileKey = () => st.fileName + "|" + st.meta.finder;
61	function loadMarks() {
62	  st.forced = new Map(); st.edits = new Map();
63	  const marks = readJSON(MARKS + fileKey()), edits = readJSON(EDITS + fileKey());
64	  for (const c of st.cands) {
65	    const m = marks[posKey(c)], e = edits[posKey(c)];
66	    if (m) st.forced.set(c.i, m);
67	    if (e) st.edits.set(c.i, e);
68	  }
69	}
70	function saveMap(prefix, map) {
71	  const out = {};
72	  for (const [j, v] of map) out[posKey(st.cands[j])] = v;
73	  writeJSON(prefix + fileKey(), out);
74	}
75	// the user's word on a candidate: "approve" (a NoR, with the lengths shown), "reject" (not one), or null (the filters decide)
76	function decide(i, d) {
77	  d ? st.forced.set(i, d === "approve" ? "in" : "out") : st.forced.delete(i);
78	  const e = { ...(st.edits.get(i) || {}) };
79	  d === "approve" ? (e.approved = true) : delete e.approved;
80	  Object.keys(e).length ? st.edits.set(i, e) : st.edits.delete(i);
81	  saveMap(MARKS, st.forced); saveMap(EDITS, st.edits); render();
82	}
83	function edit(i, change) {
84	  const e = { ...(st.edits.get(i) || {}), ...change };
85	  for (const k of Object.keys(e)) if (e[k] == null || e[k] === false) delete e[k];
86	  Object.keys(e).length ? st.edits.set(i, e) : st.edits.delete(i);
87	  saveMap(EDITS, st.edits); drawLines(st.cands[i]); render();
88	}
