90	// ---------- status ----------
91	function status(text, err) {
92	  const s = $("#status"); s.textContent = text; s.classList.toggle("err", !!err);
93	  if (st.busySince) $("#busy-text").textContent = text;
94	  if (err) busy(false);
95	}
96	// the spinner and elapsed time shown while Python loads or a finder runs. look "scan": a finder running over
97	// an image shows a photocopier's light sweeping across it instead of the spinner; "peek": the image painting
98	// as it arrives stays in view, the text in a pill below it
99	function busy(on, text, look) {
100	  clearInterval(st.busyTimer); st.busySince = on ? st.busySince || Date.now() : 0;
101	  $("#spin").classList.toggle("on", on); $("#busy").hidden = !on;
102	  $("#busy").classList.toggle("scan", on && look === "scan"); $("#busy").classList.toggle("peek", on && look === "peek");
103	  if (!on) return;
104	  $("#busy-text").textContent = text || $("#status").textContent; $("#busy-time").textContent = "";
105	  st.busyTimer = setInterval(() => { $("#busy-time").textContent = ((Date.now() - st.busySince) / 1000).toFixed(0) + " s"; }, 500);
106	}
107	function statusBar() {
108	  const t = st.times, parts = [];
109	  if (t.load != null) parts.push(`Python ${t.load.toFixed(0)} s`);
110	  if (t.open != null) parts.push(`image ${t.open.toFixed(1)} s`);
111	  if (t.detect != null) parts.push(`finding ${t.detect.toFixed(1)} s`);
112	  if (t.filter != null) parts.push(`filters ${t.filter.toFixed(0)} ms`);
113	  $("#sb-times").textContent = parts.join(" · ");
114	  $("#sb-file").textContent = st.fileName || "No image";
115	}
116	const fmt = (v, d = 2) => (v == null || !isFinite(v) ? "–" : Number(v).toFixed(d));
117	
118	// ---------- worker ----------
119	async function start() {
120	  if ("serviceWorker" in navigator) {
121	    try {
122	      await navigator.serviceWorker.register("sw.js");
123	      await navigator.serviceWorker.ready;
124	      if (!navigator.serviceWorker.controller) {
125	        // first visit: wait for the cache to take control so the downloads below are kept
126	        await Promise.race([new Promise((r) => navigator.serviceWorker.addEventListener("controllerchange", r, { once: true })),
127	                            new Promise((r) => setTimeout(r, 3000))]);
128	      }
129	    } catch (e) { console.warn("no cache for third-party files:", e); }
130	  }
131	  status("Loading Python in the background…"); $("#spin").classList.add("on");
132	  st.worker = new Worker("worker.js", { type: "module" });
133	  st.worker.onmessage = (e) => onWorker(e.data);
134	}
