586	// ---------- cards: one per candidate, in the item views and as the selection ----------
587	// The crop, turned so the NoR lies level when "align to horizon" is on, with its outlines, bars and
588	// length handles drawn over it. Cached until the options or the candidate's lengths change.
589	function crop(c, size) {
590	  const o = optsOf(c), key = JSON.stringify([size, o, st.edits.get(c.i) || null, st.show.passC, st.show.failC, result(c.i) === null]);
591	  const hit = st.crops.get(c.i + "|" + size);
592	  if (hit && hit.key === key) return hit.node;
593	  const L = linesOf(c), pad = o.pad;
594	  let th = 0, cx = (c.bb[0] + c.bb[2]) / 2, cy = (c.bb[1] + c.bb[3]) / 2;
595	  if (L) {
596	    const [[a, b], [p, q]] = L.length; cx = (a + p) / 2; cy = (b + q) / 2;
597	    if (o.align) { th = Math.atan2(q - b, p - a); if (Math.cos(th) < 0) th += Math.PI; }
598	  }
599	  const ax = [Math.cos(th), Math.sin(th)], nv = [-Math.sin(th), Math.cos(th)];
600	  const toUV = ([x, y]) => [(x - cx) * ax[0] + (y - cy) * ax[1], (x - cx) * nv[0] + (y - cy) * nv[1]];
601	  const toXY = ([u, v]) => [cx + u * ax[0] + v * nv[0], cy + u * ax[1] + v * nv[1]];
602	  // extent: every pixel of the candidate, and its lines
603	  let u0 = Infinity, u1 = -Infinity, v0 = Infinity, v1 = -Infinity;
604	  const take = (p) => { const [u, v] = toUV(p); u0 = Math.min(u0, u); u1 = Math.max(u1, u); v0 = Math.min(v0, v); v1 = Math.max(v1, v); };
605	  for (let y = 0; y < c.h; y++) for (let x = 0; x < c.w; x++) if (c.blk[y * c.w + x]) for (const [dx, dy] of [[0, 0], [1, 0], [0, 1], [1, 1]]) take([c.x0 + x + dx, c.y0 + y + dy]);
606	  if (L) for (const k of ["length", "red"]) L[k].forEach(take);
607	  u0 -= pad; u1 += pad; v0 -= pad; v1 += pad;
608	  const uw = u1 - u0, vw = v1 - v0, s = Math.max(2, Math.min(size / 10, size / Math.max(uw, vw))), dpr = devicePixelRatio || 1;
609	  const cv = document.createElement("canvas"); cv.width = Math.round(uw * s * dpr); cv.height = Math.round(vw * s * dpr);
610	  cv.style.width = uw * s + "px";
611	  const ctx = cv.getContext("2d"); ctx.imageSmoothingEnabled = false;
612	  ctx.fillStyle = "#000"; ctx.fillRect(0, 0, cv.width, cv.height);
613	  ctx.setTransform(s * dpr, 0, 0, s * dpr, 0, 0); ctx.translate(-u0, -v0);
614	  ctx.transform(ax[0], nv[0], ax[1], nv[1], 0, 0); ctx.translate(-cx, -cy);
615	  const R = Math.ceil(Math.hypot(uw, vw) / 2) + 2, sx = Math.max(0, Math.floor(cx - R)), sy = Math.max(0, Math.floor(cy - R));
616	  const sw = Math.min(st.W, Math.ceil(cx + R)) - sx, sh = Math.min(st.H, Math.ceil(cy + R)) - sy;
617	  ctx.drawImage(st.plain, sx, sy, sw, sh, sx, sy, sw, sh);
618	  if (o.borders) {
619	    ctx.lineWidth = 1 / s; ctx.strokeStyle = result(c.i) === null ? st.show.passC : st.show.failC;
620	    for (const [val, alpha] of [[1, 0.5], [2, 0.7]]) { ctx.globalAlpha = alpha; ctx.stroke(new Path2D(outline(c, c.blk, val))); }
621	    ctx.globalAlpha = 1;
622	  }
623	  const node = document.createElement("div"); node.className = "crop"; node.append(cv);
624	  if (L && (o.bars || o.lenImg || o.adjust)) node.append(cropMarks(c, L, { s, u0, v0, uw, vw, toUV, toXY, ax }));
625	  st.crops.set(c.i + "|" + size, { key, node }); return node;
626	}
