628	// bars, length labels and draggable ends over a crop, in its own turned coordinates
629	function cropMarks(c, L, g) {
630	  const o = optsOf(c), f = st.um || 1, svg = el("svg", { class: "marks", viewBox: `${g.u0} ${g.v0} ${g.uw} ${g.vw}`, width: g.uw * g.s, height: g.vw * g.s });
