632	  const draw = () => {
633	    svg.replaceChildren();
634	    if (o.bars) svg.append(line("length", "bar"), line("width", "bar"), line("red", "bar r"));
635	    if (o.lenImg) {
636	      for (const [k, cls, dy] of [["length", "", -5], ["red", "r", 11]]) {
637	        const [[a, b], [p, q]] = L[k].map(g.toUV), t = el("text", { x: (a + p) / 2, y: Math.min(b, q) + dy * px, class: cls, "font-size": 10 * px, "stroke-width": 2 * px });
638	        t.textContent = fmt(dist(L[k]) * f, 1); svg.append(t);
639	      }
640	    }
641	    if (o.adjust && result(c.i) === null) for (const k of ["length", "red"]) L[k].forEach((p, j) => {
642	      const [u, v] = g.toUV(p), h = el("circle", { cx: u, cy: v, r: 4 * px, class: "handle" + (k === "red" ? " r" : ""), "stroke-width": px });
643	      h.dataset.k = k; h.dataset.j = j; svg.append(h);
644	    });
645	  };
646	  draw();
647	  // an end slides along its own line; the result is kept in image coordinates
648	  svg.addEventListener("pointerdown", (e) => {
649	    const h = e.target.closest(".handle"); if (!h) return;
650	    e.preventDefault(); e.stopPropagation(); svg.setPointerCapture(e.pointerId);
651	    const k = h.dataset.k, j = +h.dataset.j, [A, B] = L[k], d = [B[0] - A[0], B[1] - A[1]], n = Math.hypot(...d), dir = [d[0] / n, d[1] / n];
