653	    const move = (ev) => {
654	      const pt = svg.createSVGPoint(); pt.x = ev.clientX; pt.y = ev.clientY;
655	      const q = pt.matrixTransform(svg.getScreenCTM().inverse()), P = g.toXY([q.x, q.y]);
656	      let t = (P[0] - A[0]) * dir[0] + (P[1] - A[1]) * dir[1];
657	      t = j === 0 ? Math.min(t, n - 1) : Math.max(t, 1);
658	      L[k][j] = [A[0] + t * dir[0], A[1] + t * dir[1]]; draw();
659	    };
660	    const up = () => {
661	      svg.removeEventListener("pointermove", move); svg.removeEventListener("pointerup", up);
662	      edit(c.i, { [k]: L[k].map((p) => p.map((v) => Math.round(v * 100) / 100)) });
663	    };
664	    svg.addEventListener("pointermove", move); svg.addEventListener("pointerup", up);
665	  });
666	  return svg;
667	}
