768	  const lo = s.min, hi = s.max === s.min ? s.min + 1 : s.max, cnt = new Array(bins).fill(0);
769	  for (const x of s.v) cnt[Math.min(bins - 1, Math.floor(((x - lo) / (hi - lo)) * bins))]++;
770	  const top = Math.max(...cnt), bw = W / bins;
771	  const bars = cnt.map((c, k) => `<rect x="${k * bw + 0.5}" y="${H - (c / top) * H}" width="${bw - 1}" height="${(c / top) * H}"><title>${c}</title></rect>`).join("");
772	  return `<div class="hist">${label}<br><svg width="${W}" height="${H + 14}"><g>${bars}</g>
773	    <text x="0" y="${H + 12}" fill="currentColor" font-size="10">${fmt(lo)}</text>
774	    <text x="${W}" y="${H + 12}" fill="currentColor" font-size="10" text-anchor="end">${fmt(hi)}</text></svg></div>`;
775	}
