    const [[x1, y1], [x2, y2]] = L[k];
    c.lineEl.append(el("line", { x1, y1, x2, y2, ...(cls ? { class: cls } : {}) }));
  }
}

// the result shown for candidate i: null = pass, else a failure reason
function result(i) {
