  const sw = Math.min(st.W, Math.ceil(cx + R)) - sx, sh = Math.min(st.H, Math.ceil(cy + R)) - sy;
  ctx.drawImage(st.plain, sx, sy, sw, sh, sx, sy, sw, sh);
