    e.preventDefault(); e.stopPropagation(); svg.setPointerCapture(e.pointerId);
    const k = h.dataset.k, j = +h.dataset.j, [A, B] = L[k], d = [B[0] - A[0], B[1] - A[1]], n = Math.hypot(...d), dir = [d[0] / n, d[1] / n];
