    root,
    repo,
    defaultBranch: text('CLAUDINITE_DEFAULT_BRANCH'),
    pack,
    task,
    item,
    context: text('CLAUDINITE_CONTEXT') === null ? [] : text('CLAUDINITE_CONTEXT').split('\n'),
    target,
